import re

class SyntaxError(Exception):
    pass

class NameError(Exception):
    pass

class ZeroDivisionError(Exception):
    pass

class Calculator:
    def __init__(self):
        self.variables = {}

    def get_value(self, token):
        if re.match(r'^-?\d+(\.\d+)?$', token):
            return float(token) if '.' in token else int(token)
        if token in self.variables:
            return self.variables[token]
        raise NameError(f"Tanımsız değişken veya fonksiyon: {token}")

    def tokenize(self, expression):
        # Tokenize işlemi için regex kullanıyoruz
        # Sayılar, operatörler, parantezler ve isimler
        tokens = re.findall(r'\d+\.\d+|\d+|[a-zA-Z_][a-zA-Z0-9_]*|==|!=|<=|>=|[+\-*/%**()]|\S', expression)
        # Not: ** iki karakterli bir operatör olduğu için regex'te dikkat edilmeli. 
        # Ancak re.findall sırayla gider. Basitlik için önce çoklu operatörleri yakalayalım.
        tokens = []
        i = 0
        while i < len(expression):
            if expression[i:i+2] == '**':
                tokens.append('**')
                i += 2
            elif expression[i] in ' \t\n\r':
                i += 1
                continue
            elif expression[i].isalnum() or expression[i] in '_':
                match = re.match(r'[a-zA-Z_][a-zA-Z0-9_]*|\d+\.\d+|\d+', expression[i:])
                if match:
                    tokens.append(match.group())
                    i += len(match.group())
                    continue
            elif expression[i] in '+-*/%()':
                tokens.append(expression[i])
                i += 1
            else:
                # Bilinmeyen karakter varsa SyntaxError fırlatmak yerine token olarak alalım, parser hata versin
                tokens.append(expression[i])
                i += 1
        return tokens

    def parse_expression(self, tokens):
        if not tokens:
            raise SyntaxError("Boş ifade")

        # Shunting-yard algoritması veya Recursive Descent Parser kullanabiliriz.
        # Karmaşık öncelikler (özellikle ** ve unary -) için Recursive Descent daha güvenlidir.
        self.tokens = tokens
        self.pos = 0
        result = self._parse_assignment() # Aslında en üst seviye atama veya ifade olabilir
        return result

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self, expected=None):
        token = self._peek()
        if expected and token != expected:
            raise SyntaxError(f"Beklenen {expected}, bulundu {token}")
        self.pos += 1
        return token

    def _parse_assignment(self):
        # Atama kontrolü: ad = ifade
        start_pos = self.pos
        try:
            if self.pos < len(self.tokens) and re.match(r'[a-zA-Z_][a-zA-Z0-9_]*', self.tokens[self.pos]):
                name = self.tokens[self.pos]
                # Bakalım bir sonraki token '=' mi?
                if self.pos + 1 < len(self.tokens) and self.tokens[self.pos+1] == '=':
                    self.pos += 2 # name ve '=' tüket
                    val = self._parse_expression_logic()
                    return val, name

            # Eğer atama değilse ifade olarak değerlendir
            val = self._parse_expression_logic()
            return val, None
        except Exception as e:
            if isinstance(e, (SyntaxError, NameError, ZeroDivisionError)):
                raise e
            raise SyntaxError("Söz dizimi hatası")

    def _parse_expression_logic(self):
        # En düşük öncelik: + ve - (toplama/çıkarma)
        node = self._parse_term()
        while self._peek() in ('+', '-'):
            op = self._consume()
            right = self._parse_term()
            if op == '+': node += right
            else: node -= right
        return node

    def _parse_term(self):
        # * / %
        node = self._parse_exponent()
        while self._peek() in ('*', '/', '%'):
            op = self._consume()
            right = self._parse_exponent()
            if op == '*':
                node *= right
            elif op == '/':
                if right == 0: raise ZeroDivisionError("Sıfıra bölme")
                node /= right
            elif op == '%':
                if right == 0: raise ZeroDivisionError("Sıfıra bölme")
                node %= right
        return node

    def _parse_exponent(self):
        # ** (Sağdan birleşir, unary -'den sonra gelir)
